    private static List<Object> alerts(Map<String,Object> p,List<String> ids,Map<String,Map<String,Object>> datasets,Map<String,Scope> scopes,Map<String,Set<String>> selected,Set<Key> universe){var output=new ArrayList<Object>();if(!Boolean.TRUE.equals(p.get("zero_overlap_alert")))return output;for(String id:ids){var ownTested=new TreeSet<String>();var otherTested=new TreeSet<String>();var otherHits=new TreeSet<String>();for(Key key:universe)for(String other:ids){Row row=scopes.get(other).rows.get(key);if(row!=null&&row.estimable)(other.equals(id)?ownTested:otherTested).add(key.id());}for(String other:ids)if(!other.equals(id))otherHits.addAll(selected.get(other));ownTested.retainAll(otherTested);var own=new TreeSet<>(selected.get(id));own.retainAll(ownTested);otherHits.retainAll(ownTested);var shared=new TreeSet<>(own);shared.retainAll(otherHits);boolean alert=ownTested.size()>=integer(p,"minimum_shared_tested")&&own.size()>=integer(p,"minimum_selected_features")&&!otherHits.isEmpty()&&shared.isEmpty();output.add(Map.of("dataset",id,"cohort",datasets.get(id).get("cohort"),"shared_estimable_tuples",ownTested.size(),"selected_own_shared",own.size(),"selected_other_shared",otherHits.size(),"shared_selected_tuples",shared.size(),"alert",alert,"interpretation",alert?"Review coverage, power, variants and a registered cohort omission; no automatic exclusion":"No qualifying zero-overlap alert; this does not establish comparable power or independent replication"));}return output;}
