    static Key key(String feature,String mask,String test)throws IOException {for(String value:List.of(feature,mask,test))if(value.isBlank()||value.chars().anyMatch(Character::isISOControl))throw new IOException("Rare overlap identities must be explicit nonblank set/mask/test labels without control characters");return new Key(feature,mask,test);}
    private static String encoded(String value){return Base64.getUrlEncoder().withoutPadding().encodeToString(value.getBytes(StandardCharsets.UTF_8));}
    private static double probability(String value)throws IOException {if(Set.of("","NA","NaN",".").contains(value))return Double.NaN;try{double p=Double.parseDouble(value);if(!Double.isFinite(p)||p<0||p>1)throw new IOException("Invalid rare overlap probability");return p;}catch(NumberFormatException bad){throw new IOException("Malformed rare overlap probability",bad);}}
    private static String same(Row a,Row b){return a!=null&&b!=null&&a.signed&&b.signed&&Double.isFinite(a.beta)&&Double.isFinite(b.beta)&&a.beta!=0&&b.beta!=0?String.valueOf(Math.signum(a.beta)==Math.signum(b.beta)):"unavailable";}
    private static boolean hit(double q,double alpha,boolean strict){return Double.isFinite(q)&&(strict?q<alpha:q<=alpha);}
    private static int integer(Map<String,Object> p,String field){return ((Number)p.get(field)).intValue();}
    private static String role(String id,Set<String> discovery,Set<String> validation){return discovery.contains(id)?"discovery":validation.contains(id)?"validation":"other";}
    private static String value(double n){return Double.isFinite(n)?String.valueOf(n):"NA";}
    private static Result finish(Context c,Map<String,Object> p,Map<String,Object> details,boolean complete,boolean performed,String reason)throws IOException {details.put("method_report",Map.of("performed",performed,"operation","rare_cohort_overlap","method","Exact primary set/mask/test membership preserving complete joint source families","parameters",p,"software","JLinAlg "+JLinAlgCli.version(),"references",List.of("https://doi.org/10.1109/TVCG.2014.2346248")));details.put("interpretation",reason);if(!complete)details.put("needs",List.of(StudyNeed.review("rare-cohort-overlap:"+c.operation().get("hypothesis")+":"+StudyFindingInventory.hash(reason).substring(0,20),"Resolve rare-set cohort overlap prerequisites",reason,true).document()));write(c.outputDirectory().resolve("cohort-overlap.yaml"),details);var outputs=new ArrayList<String>();try(var paths=Files.walk(c.outputDirectory())){paths.filter(Files::isRegularFile).sorted().forEach(path->outputs.add(c.outputDirectory().relativize(path).toString().replace('\\','/')));}return new Result(complete?State.COMPLETE:State.WAITING_FOR_INPUT,reason,outputs,details);}
